import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Kubernetes test plan","description":"","frontmatter":{},"headers":[],"relativePath":"development/kubernetes-test-plan.md","filePath":"development/kubernetes-test-plan.md","lastUpdated":null}'),o={name:"development/kubernetes-test-plan.md"};function r(n,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="kubernetes-test-plan" tabindex="-1">Kubernetes test plan <a class="header-anchor" href="#kubernetes-test-plan" aria-label="Permalink to &quot;Kubernetes test plan&quot;">​</a></h1><h2 id="automated-gates" tabindex="-1">Automated gates <a class="header-anchor" href="#automated-gates" aria-label="Permalink to &quot;Automated gates&quot;">​</a></h2><ol><li>Restore/build the operator with warnings as errors.</li><li>Run the xUnit resource identity and behavior tests.</li><li>Build the TypeScript UI and run its unit/E2E tests.</li><li>Build the operator container and scan it with Trivy.</li><li>Lint Helm and verify generated CRDs/RBAC/deployment are valid YAML.</li><li>Run the AOT probe; it is informative until KubeOps publishes NativeAOT support.</li></ol><h2 id="k3s-integration-scenario" tabindex="-1">k3s integration scenario <a class="header-anchor" href="#k3s-integration-scenario" aria-label="Permalink to &quot;k3s integration scenario&quot;">​</a></h2><p>The Compose smoke script starts k3s, waits for <code>/readyz</code>, applies the generated KubeOps manifests, and the integration workflow creates valid, disabled, and invalid resources. It verifies <code>Repository=Ready</code>, <code>Repository=Disabled</code>, <code>RepositorySource=Ready</code>, and <code>ScanPolicy=Error</code>. It then checks the operator health/metrics endpoints, API repository compatibility endpoint, PostgreSQL readiness, and the browser E2E suite.</p><h2 id="failure-and-lifecycle-cases" tabindex="-1">Failure and lifecycle cases <a class="header-anchor" href="#failure-and-lifecycle-cases" aria-label="Permalink to &quot;Failure and lifecycle cases&quot;">​</a></h2><ul><li>invalid CRD payload rejected by schema validation;</li><li>disabled Repository becomes <code>Disabled</code>;</li><li>RepositorySource without provider credentials remains safely <code>Ready</code> with an explanatory status message;</li><li>operator restart re-watches existing objects and reconciles them again;</li><li>deletion does not leave owned resources or stuck finalizers;</li><li>API server unavailability causes retries and a non-ready pod;</li><li>least-privilege Role permits CRDs, Jobs, and referenced Secrets only;</li><li>two replicas exercise KubeOps leader election without duplicate side effects.</li></ul><p>The first six automated gates and the local Compose smoke scenario are executed by CI. The failure/lifecycle cases remain a release-certification checklist where an external provider or failure injection is required.</p><h2 id="current-implementation-evidence" tabindex="-1">Current implementation evidence <a class="header-anchor" href="#current-implementation-evidence" aria-label="Permalink to &quot;Current implementation evidence&quot;">​</a></h2><ul><li>Passed locally: <code>dotnet test AegisScan.sln</code> (6 tests), frontend typecheck/unit/build (9 tests), Helm lint/template, Linux NativeAOT publish probe, Docker image build, k3s CRD installation, live reconciliation, PostgreSQL readiness, operator/API health, and the full Compose Playwright suite (7 tests).</li><li>The local Compose run used <code>AEGIS_WEB_PORT=3001</code> because another process owned port 3000. The default remains port 3000, and the configurable port is supported by <code>docker-compose.yml</code> and <code>scripts/compose-e2e.ps1</code>. The reproducible CI test is implemented in <code>.github/workflows/kubernetes-integration.yml</code>.</li></ul>',10)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
